p=Path('src/components/CodePlayground.tsx');s=p.read_text(encoding='utf-8');s="import type {GameRunEvidence,GameRunReason} from '../core/codeGames';\n"+s;s=s.replace('canGenerate?:boolean}', 'canGenerate?:boolean;onRunning?:(running:boolean)=>void;onRunFinished?:(evidence:GameRunEvidence)=>void}')
